from math import sqrt

def is_prime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int):
    fib_sequence = [0, 1]
    while len(fib_sequence) < n:
        fib = fib_sequence[-1] + fib_sequence[-2]
        if is_prime(fib):
            fib_sequence.append(fib)
    return fib_sequence[n-1]

# Test cases
