def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [0]
    elif n == 1:
        return [3]
    elif n == 2:
        return [1, 3]

    # Initialize the first three numbers of the sequence
    tribonacci = [0, 3, 2]

    # Calculate the next numbers in the sequence
    for i in range(3, n + 1):
        tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i - 3])

    return tribonacci
