from typing import List

def largest_smallest_integers(lst: List[int]) -> Tuple[int, int]:
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    if not lst:
        return (None, None)

    negative_integers = [num for num in lst if num < 0]
    positive_integers = [num for num in lst if num >= 0]

    if not negative_integers and not positive_integers:
        return (None, None)

    if not negative_integers:
        return (max(positive_integers), min(positive_integers))
    elif not positive_integers:
        return (max(negative_integers), min(negative_integers))
    else:
        return (max(negative_integers), min(positive_integers))

# Check function with provided data points
